INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-0000002-0000-0000-0000-000000000001', 'q2000002-0000-0000-0000-000000000001', 'UI (User Interface) adalah tampilan visual dan elemen interaksi yang digunakan pengguna untuk berinteraksi dengan produk, sedangkan UX (User Experience) adalah keseluruhan pengalaman pengguna saat menggunakan produk, termasuk kemudahan, kenyamanan, dan kepuasan.', ARRAY['ui', 'tampilan visual', 'antarmuka', 'ux', 'pengalaman pengguna', 'kenyamanan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000002', 'q2000002-0000-0000-0000-000000000002', 'Design Thinking bertujuan menghasilkan solusi inovatif yang berpusat pada kebutuhan pengguna melalui proses memahami masalah, menghasilkan ide, membuat prototipe, dan melakukan pengujian.', ARRAY['solusi inovatif', 'kebutuhan pengguna', 'human centered', 'pemecahan masalah']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000003', 'q2000002-0000-0000-0000-000000000003', 'Empathize adalah tahap memahami pengguna secara mendalam melalui observasi, wawancara, dan riset untuk mengetahui kebutuhan, perilaku, masalah, serta motivasi mereka.', ARRAY['memahami pengguna', 'observasi', 'wawancara', 'kebutuhan', 'masalah']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000004', 'q2000002-0000-0000-0000-000000000004', 'Define adalah tahap merumuskan masalah utama pengguna berdasarkan hasil riset dan empati sehingga tim memiliki fokus yang jelas dalam mencari solusi.', ARRAY['merumuskan masalah', 'fokus', 'hasil riset', 'kebutuhan pengguna']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000005', 'q2000002-0000-0000-0000-000000000005', 'Ideate adalah proses menghasilkan sebanyak mungkin ide solusi melalui brainstorming dan kreativitas untuk menyelesaikan masalah pengguna.', ARRAY['brainstorming', 'ide', 'solusi', 'kreativitas']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000006', 'q2000004-0000-0000-0000-000000000001', 'Prototype digunakan untuk memvisualisasikan ide dalam bentuk sederhana agar dapat diuji, dievaluasi, dan diperbaiki sebelum dikembangkan menjadi produk sebenarnya.', ARRAY['visualisasi ide', 'pengujian', 'evaluasi', 'perbaikan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000007', 'q2000004-0000-0000-0000-000000000002', 'Karena tahap Test memberikan feedback nyata dari pengguna sehingga tim dapat mengetahui kelemahan solusi dan melakukan perbaikan berdasarkan kebutuhan pengguna.', ARRAY['feedback', 'validasi', 'pengguna', 'perbaikan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000008', 'q2000004-0000-0000-0000-000000000003', 'Empathy Map adalah alat untuk memahami pengguna melalui aspek Says, Thinks, Feels, dan Does sehingga tim dapat memahami perilaku dan kebutuhan pengguna secara lebih mendalam.', ARRAY['empathy map', 'says', 'thinks', 'feels', 'does']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000009', 'q2000004-0000-0000-0000-000000000004', 'User Research membantu memahami kebutuhan, masalah, perilaku, dan ekspektasi pengguna sehingga keputusan desain didasarkan pada data, bukan asumsi.', ARRAY['user research', 'kebutuhan', 'data', 'perilaku pengguna', 'bukan asumsi']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000010', 'q2000004-0000-0000-0000-000000000005', 'Wireframe adalah kerangka atau blueprint antarmuka yang menggambarkan struktur halaman, tata letak konten, dan navigasi sebelum desain visual dibuat.', ARRAY['blueprint', 'struktur halaman', 'tata letak', 'wireframe']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000011', 'q2000006-0000-0000-0000-000000000001', 'Usability adalah tingkat kemudahan pengguna dalam mempelajari, memahami, dan menggunakan suatu produk untuk mencapai tujuan mereka secara efektif dan efisien.', ARRAY['kemudahan penggunaan', 'efektif', 'efisien', 'pengguna']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000012', 'q2000006-0000-0000-0000-000000000002', 'Karena biaya, waktu, dan risiko perubahan akan meningkat ketika produk sudah dikembangkan atau dirilis. Perbaikan sejak awal jauh lebih murah dan efisien.', ARRAY['biaya', 'risiko', 'efisiensi', 'perubahan awal']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000013', 'q2000006-0000-0000-0000-000000000003', 'Perubahan antarmuka yang terlalu drastis tanpa mempertimbangkan kebiasaan pengguna dapat menimbulkan kebingungan dan menurunkan pengalaman pengguna.', ARRAY['perubahan drastis', 'kebiasaan pengguna', 'kebingungan', 'ux']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000014', 'q2000006-0000-0000-0000-000000000004', 'Keberhasilan teknologi tidak hanya ditentukan oleh kecanggihan fitur, tetapi juga oleh penerimaan pengguna, kenyamanan penggunaan, privasi, dan kebutuhan pasar.', ARRAY['penerimaan pengguna', 'privasi', 'kebutuhan pasar', 'teknologi']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000002-0000-0000-0000-000000000015', 'q2000006-0000-0000-0000-000000000005', 'Karena tujuan utama suatu produk adalah membantu pengguna mencapai kebutuhannya. Dengan memahami pengguna, produk menjadi lebih relevan, mudah digunakan, bermanfaat, dan memiliki peluang keberhasilan yang lebih tinggi.', ARRAY['user-centered design', 'kebutuhan pengguna', 'relevan', 'mudah digunakan', 'manfaat']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb);
